from scipy.optimize import least_squares
def model(p,t,P):
    a,b,c,d,e,f,k,m=p
    return a*P**2 + b*np.log(1+c*t)*np.sqrt(P) + d*P**2/(1+e*P**2) + f*t**k*P**m
def res(p):
    r=model(p,t,P)-dP_dt
    return np.where(np.isfinite(r),r,1e3)
